let input = '';
process.stdin.on('data', (d) => { input += d; });
process.stdin.on('end', () => {
  const mode = process.argv[2];
  if (mode === 'block') { process.stdout.write(JSON.stringify({ decision: 'block', reason: 'file hook blocks' }) + '\n'); process.exit(0); }
  if (mode === 'err') { process.stderr.write('file hook failed\n'); process.exit(1); }
  if (mode === 'two') { process.stderr.write('file hook exit two\n'); process.exit(2); }
  process.exit(0);
});
